// Le champ "output" contient la structure renvoyée par AI Agent 1 (avec ```json ... ```)
let txt = $json.output ?? "";

// 1. Supprime l’ouverture ```json (insensible à la casse + espaces éventuels)
txt = txt.replace(/```json\s*/i, "");

// 2. Supprime tous les autres ``` éventuels (fermeture)
txt = txt.replace(/```/g, "").trim();

// 3. Retourne un nouvel item avec la clé "rawPlan"
return [
  {
    rawPlan: txt          // <-- Flutter lira res["rawPlan"]
  }
];

// 1. Récupère la chaîne brute où qu’elle se trouve
const raw = $json.output || $json.rawPlan || "";

if (!raw) {
  throw new Error(
    "Aucune propriété 'output' ou 'rawPlan' trouvée dans l'item entrant."
  );
}

// 2. Nettoie toutes les balises ```json … ```
const cleaned = raw
  .replace(/```json\s*/i, "")   // supprime l'ouverture (insensible à la casse)
  .replace(/```/g, "")          // supprime toutes les fermetures
  .trim();

// 3. Parse le JSON proprement
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  throw new Error("JSON invalide : " + err.message);
}

// 4. Renvoie un seul item avec les deux formats
return [
  {
    json: {
      rawPlan: cleaned,   // chaîne prête à stocker/télécharger
      parsedPlan: parsed  // objet prêt à être manipulé
    }
  }
];

return items.map(item => {
  const parsedData = typeof item.json.parparsed === 'string' 
    ? JSON.parse(item.json.parparsed) 
    : item.json.parparsed;

  // Créer un objet simple avec au moins un champ
  return {
    json: {
      plan_metadata: {
        plan_duration: parsedData.plan_duration,
        training_goal: parsedData.training_goal,
        sessions_per_week: parsedData.sessions_per_week
      },
      weekly_sessions_data: JSON.stringify(parsedData.weekly_sessions)
    }
  };
});

const b = items[0].json.body || {};

// 1. Gestion sécurisée de l'objectif de temps
const t = String(b.objectiveTime || '').trim();
const parts = t.split(':').map(Number);

// 2. Correction du calcul des secondes (gère les formats "mm:ss" ou "hh:mm:ss")
let objSec;
if (parts.length === 3) {
  // Format "hh:mm:ss"
  objSec = parts[0] * 3600 + parts[1] * 60 + parts[2];
} else if (parts.length === 2) {
  // Format "mm:ss" ou "hh:mm" selon la valeur (ex: "04:20" = 4h20min)
  // Si la première valeur > 60, on considère que c'est en minutes
  if (parts[0] < 60) {
    objSec = parts[0] * 3600 + parts[1] * 60; // format "hh:mm"
  } else {
    objSec = parts[0] * 60 + parts[1]; // format "mm:ss"
  }
} else {
  objSec = 0; // Valeur par défaut
}

// 3. Conversion des paramètres en nombres
const vma = Number(b.vma);
const dist = Number(b.distance);
const spw = Number(b.sessionsPerWeek);

// 4. Calcul correct de la différence (objectif - capacité actuelle)
// Valeur positive = objectif plus ambitieux que la capacité actuelle
const vmaPace = 3600 / vma / 0.85; // Allure cible ajustée (en sec/km)
const targetPace = objSec / dist;  // Allure objectif (en sec/km)
const diff = vmaPace - targetPace; // positif = objectif plus rapide que capacité

// 5. Calcul des semaines avec gestion des cas limites
let weeks;
if (vma <= 0 || dist <= 0 || spw <= 0) {
  weeks = null; // Données invalides
} else if (diff >= 30) {
  weeks = Math.ceil(20 * (3 / spw)); // Objectif très ambitieux
} else if (diff >= 20) {
  weeks = Math.ceil(16 * (3 / spw));
} else if (diff >= 15) {
  weeks = Math.ceil(12 * (3 / spw));
} else if (diff >= 10) {
  weeks = Math.ceil(10 * (3 / spw));
} else if (diff >= 5) {
  weeks = Math.ceil(8 * (3 / spw));
} else if (diff >= 0) {
  weeks = Math.ceil(6 * (3 / spw)); // Objectif légèrement ambitieux
} else {
  // Objectif réalisable immédiatement (diff < 0)
  weeks = 2; // Minimum de 2 semaines pour consolider la base
}

return [{
  json: {
    durationWeeks: weeks,
    isRealistic: weeks !== null,
    coachtone: b.coachtone || 'professionnel',
    // Données de diagnostic (utile pour le debug)
    debug: {
      vmaPace,
      targetPace,
      diff,
      isValid: vma > 0 && dist > 0 && spw > 0
    }
  }
}];
